34	method queryFast(a: array<int>, c: array<int>, i: int, j: int) returns (r: int)
35	  requires is_prefix_sum_for(a,c)
36	  ensures r == sum(a, i, j)
37	{
38	  var k := i;
39	  proof(a, 0, j, k);
40	  r := c[j] - c[i];
41	}
