58	method from_array<T>(a: array<T>) returns (l: List<T>)
59	  ensures forall i: int :: 0 <= i < a.Length ==> mem(a[i], l)
60	  ensures forall x: T :: mem(x, l) ==> exists y: int :: 0 <= y < a.Length && a[y] == x
61	{
62	  l := Nil;
63	  var i := a.Length - 1;
64	  while i >= 0
65	    invariant 0 <= i+1 <= a.Length
66	    invariant forall j: int :: i < j < a.Length ==> mem(a[j], l)
67	    invariant forall x: T :: mem(x, l) ==> exists y: int :: i+1 <= y < a.Length && a[y] == x
68	    decreases i
69	  {
