p='program.dfy'
s=open(p).read()
s=s.replace("""  ensures sum(a, i, k) + sum(a, k, j) == sum(a, i, j)
""","""  ensures sum(a, i, k) + sum(a, k, j) == sum(a, i, j)
  decreases j
{
  if k < j {
    proof(a, i, j-1, k);
  }
}
""",1)
open(p,'w').write(s)
